import type { E2EConfig } from 'e2e';
import { web } from '@e2e-dev/web';
import { chatgpt } from 'e2e/oauth/chatgpt';
export default {
  projectId: 'dotagents-e2e-trial',
  targets: [{ name: 'desktop', engine: web({ viewport: { width: 1280, height: 800 } }), app: { url: 'http://127.0.0.1:4187' } }],
  tests: ['tests/*.e2e.ts'],
  timeout: 45000, assertionTimeout: 2000, actionTimeout: 5000,
  launchTimeout: 15000, cleanupTimeout: 5000, workers: 1, retries: 0,
  trace: 'on', cache: { mode: 'read-write', dir: 'replay-cache' },
  reporters: ['list', 'junit'],
  agents: { default: { model: chatgpt('gpt-6-luna'), maxSteps: 8, maxModelCalls: 5, maxInputTokens: 12000 } },
} satisfies E2EConfig;

tests/cases.pw.ts.content:
import { test, expect } from '@playwright/test';
test('search', async ({ page }) => {
  await page.goto('/');
  await page.getByLabel('商品名・商品コードで検索', { exact: true }).fill('ノート');
  await expect(page.getByRole('rowheader')).toHaveText(['青いノート', '赤いノート']);
  await expect(page.getByText('全4件中2件を表示', { exact: true })).toBeVisible();
});
test('clear', async ({ page }) => {
  await page.goto('/');
  await page.getByLabel('並び順', { exact: true }).selectOption('descending');
  await page.getByLabel('商品名・商品コードで検索', { exact: true }).fill('存在しない商品');
  await expect(page.getByText('該当する商品はありません', { exact: true })).toBeVisible();
  await page.getByRole('button', { name: '検索をクリア', exact: true }).click();
  await expect(page.getByLabel('商品名・商品コードで検索', { exact: true })).toHaveValue('');
  await expect(page.getByRole('rowheader')).toHaveText(['白いマグ', '黒いペン', '赤いノート', '青いノート']);
  await expect(page.getByLabel('並び順', { exact: true })).toHaveValue('descending');
});
test('order', async ({ page }) => {
  await page.goto('/');
  await page.getByLabel('並び順', { exact: true }).selectOption('descending');
  await page.reload();
  await expect(page.getByLabel('並び順', { exact: true })).toHaveValue('descending');
  await expect(page.getByRole('rowheader')).toHaveText(['白いマグ', '黒いペン', '赤いノート', '青いノート']);
});

