import { test, expect } from 'e2e';
test('search', async ({ app, screen, browser, agent }) => {
  await app.open('/');
  await agent.act('商品名・商品コードの検索欄に「ノート」を入力する');
  await expect(screen.getByRole('rowheader')).toHaveText(['青いノート', '赤いノート']);
  await expect(screen.getByText('全4件中2件を表示', { exact: true })).toBeVisible();
});
test('clear', async ({ app, screen, browser, agent }) => {
  await app.open('/');
  await screen.getByLabel('並び順', { exact: true }).selectOption({ value: 'descending' });
  await screen.getByLabel('商品名・商品コードで検索', { exact: true }).fill('存在しない商品');
  await expect(screen.getByText('該当する商品はありません', { exact: true })).toBeVisible();
  await agent.act('検索をクリアするボタンをクリックして検索を解除する');
  await expect(screen.getByLabel('商品名・商品コードで検索', { exact: true })).toHaveValue('');
  await expect(screen.getByRole('rowheader')).toHaveText(['白いマグ', '黒いペン', '赤いノート', '青いノート']);
  await expect(screen.getByLabel('並び順', { exact: true })).toHaveValue('descending');
});
test('order', async ({ app, screen, browser, agent }) => {
  await app.open('/');
  await agent.act('並び順を商品名の降順に変更する');
  await browser.reload();
  await expect(screen.getByLabel('並び順', { exact: true })).toHaveValue('descending');
  await expect(screen.getByRole('rowheader')).toHaveText(['白いマグ', '黒いペン', '赤いノート', '青いノート']);
});

